script:
(function () {
  'use strict';
  // Closed-end vehicle lease payment (the standard US method).
  //   Gross cap cost = negotiated price + fees rolled in + amount owed on trade-in.
  //   Cap cost reduction = down payment + trade-in value + rebates.
  //   Adjusted cap cost (A) = gross - reduction.  Residual (R) = residual % x MSRP (or a dollar amount).
  //   Depreciation fee = (A - R) / months.  Finance (rent) charge = (A + R) x money factor.
  //   Money factor = APR / 2400.  Monthly tax = (depreciation + finance) x sales tax rate.
  // Verified in Node (scratchpad tests/w2loans): $50,000 price, $10,000 down, $24,000 residual,
  //   MF 0.00208, 36 months, 7% tax -> depreciation $444.44, rent charge $133.12, base $577.56,
  //   with tax $617.99 (hand calculation); MF 0.0025 <-> 6% APR; 0 money factor gives a
  //   depreciation-only payment; residual above the adjusted cap cost is rejected; no NaN on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function lease(o) {
    var gross = o.price + o.fees + o.owed;
    var reduction = o.down + o.trade + o.rebate;
    var adjusted = gross - reduction;
    var depreciation = (adjusted - o.residual) / o.months;
    var finance = (adjusted + o.residual) * o.mf;
    var base = depreciation + finance;
    var tax = base * o.taxRate / 100;
    return { gross: gross, reduction: reduction, adjusted: adjusted, depreciation: depreciation,
             finance: finance, base: base, tax: tax, payment: base + tax };
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['lsPayment', 'lsBase', 'lsSigning', 'lsTotal', 'lsGross', 'lsReduction', 'lsAdjusted', 'lsResidualOut', 'lsMf', 'lsApr']
      .forEach(function (id) { setText(id, '–'); });
    el('lsNegative').hidden = true;
    el('lsBreakdown').innerHTML = '';
  }

  function update() {
    var msrp = read('lsMsrp'), price = read('lsPrice'), months = read('lsTerm'), rate = read('lsRate'),
        residualIn = read('lsResidual'), down = read('lsDown', true), taxRate = read('lsTaxRate', true),
        trade = read('lsTrade', true), owed = read('lsOwed', true), rebate = read('lsRebate', true), fees = read('lsFees', true);
    var mfUnit = el('lsRateUnit').value === 'mf', residualPct = el('lsResidualUnit').value === 'percent';
    var error = el('lsError'), msg = '';
    var mf = mfUnit ? rate : rate / 2400;
    if (isNaN(price) || price <= 0) msg = 'Enter a negotiated price greater than $0.';
    else if (residualPct && (isNaN(msrp) || msrp <= 0)) msg = 'Enter the MSRP, which the residual percentage is based on.';
    else if (isNaN(months) || months < 1 || months > 84 || months % 1 !== 0) msg = 'Enter a lease term of 1 to 84 whole months.';
    else if (isNaN(rate) || rate < 0 || mf > 0.01) msg = mfUnit ? 'Enter a money factor from 0 to 0.01.' : 'Enter an APR from 0% to 24%.';
    else if (isNaN(residualIn) || residualIn < 0) msg = 'Enter a residual value of 0 or more.';
    else if (residualPct && residualIn > 100) msg = 'Enter a residual percentage of 100% or less.';
    else if ([down, taxRate, trade, owed, rebate, fees].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    var residual = residualPct ? msrp * residualIn / 100 : residualIn;
    var r;
    if (!msg) {
      r = lease({ price: price, fees: fees, owed: owed, down: down, trade: trade, rebate: rebate, residual: residual, months: months, mf: mf, taxRate: taxRate });
      if (r.adjusted <= 0) msg = 'Your down payment, trade-in and rebates cover the whole capitalized cost, so there is nothing to lease.';
      else if (r.adjusted < residual) msg = 'The residual value is higher than the adjusted capitalized cost. Lower the residual or the down payment.';
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    setText('lsPayment', money.format(r.payment));
    setText('lsBase', money.format(r.base));
    setText('lsSigning', money.format(down + r.payment));
    setText('lsTotal', money.format(down + r.payment * months));
    setText('lsGross', money.format(r.gross));
    setText('lsReduction', money.format(r.reduction));
    setText('lsAdjusted', money.format(r.adjusted));
    setText('lsResidualOut', money.format(residual) + (msrp > 0 ? ' (' + (residual / msrp * 100).toFixed(1) + '% of MSRP)' : ''));
    setText('lsMf', mf.toFixed(5));
    setText('lsApr', (mf * 2400).toFixed(2) + '%');
    el('lsNegative').hidden = !(owed > trade);
    setText('lsNegativeAmount', money.format(Math.max(0, owed - trade)));
    var rows = [['Depreciation', r.depreciation], ['Finance (rent) charge', r.finance], ['Sales tax', r.tax], ['Total payment', r.payment]];
    el('lsBreakdown').innerHTML = rows.map(function (row) {
      return '<tr><th scope="row">' + row[0] + '</th><td>' + money.format(row[1]) + '</td><td>' + money.format(row[1] * months) + '</td></tr>';
    }).join('');
  }

  function round(v, places) { var f = Math.pow(10, places); return Math.round(v * f) / f; }

  function switchRateUnit() {
    var v = read('lsRate');
    if (isNaN(v)) return;
    el('lsRate').value = String(el('lsRateUnit').value === 'apr' ? round(v * 2400, 3) : round(v / 2400, 6));
    el('lsRate').step = el('lsRateUnit').value === 'apr' ? '0.01' : '0.00005';
  }

  function switchResidualUnit() {
    var v = read('lsResidual'), msrp = read('lsMsrp');
    if (isNaN(v) || !(msrp > 0)) return;
    el('lsResidual').value = String(el('lsResidualUnit').value === 'dollar' ? Math.round(msrp * v / 100) : round(v / msrp * 100, 2));
    el('lsResidual').step = el('lsResidualUnit').value === 'dollar' ? '100' : '1';
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lsForm');
    if (!form) return;
    el('lsRateUnit').addEventListener('change', switchRateUnit);
    el('lsResidualUnit').addEventListener('change', switchResidualUnit);
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
